import { atom, read, update } from 'claude-code'
import type { Register } from 'claude-code'

import type { Blocked } from '../types'
import { touchesEnv, verdict } from './rules'

const blocked = atom({ plugin: 'guard', key: 'blocked' } as const, {} as Blocked)

export const register: Register = on => {
  on('tool.call', async ($, e, next) => {
    const reason = verdict(e.tool, e as unknown as Record<string, unknown>)
    if (!reason) return next(e)

    await update($, blocked, b => ({ ...b, [e.tool_use_id]: reason }))
    $.ui.log(`guard blocked: ${reason}`, { to: 'debug' })
    return { deny: `Blocked by guard: ${reason}. Do not retry or work around this.` }
  }).catch(($, e, next) =>
    next.called ? next(e) : { deny: 'guard: its check failed, so the call was blocked.' },
  )

  on('prompt.mention', ($, e, next) => {
    const env = touchesEnv(e.path)
    return env ? { deny: `guard: ${env} holds secrets` } : next(e)
  }).catch(($, e, next) => (next.called ? next(e) : { deny: 'guard: its check failed.' }))

  on('ui.render', { component: 'ToolResult' }, async ($, e, next) => {
    const reason = (await read($, blocked))[e.requestId]
    if (!reason) return next(e)

    const { Text } = $.ui.resolve(e)
    return <Text color="red" bold>✕ Blocked: {reason}</Text>
  })
}

