// A .env file: .env, .env.local, prod.env. Templates (.env.example etc.) stay readable.
const ENV = /(^|[^\w.-])([\w-]*\.env|\.env(\.[\w.-]+)?)(?=$|[^\w.-])/g
const TEMPLATE = /\.(example|sample|template|dist)$/

export function touchesEnv(text: string): string | undefined {
  for (const m of text.matchAll(ENV)) {
    const name = m[2]!
    if (!TEMPLATE.test(name)) return name
  }
  return undefined
}

const DESTRUCTIVE: ReadonlyArray<[RegExp, string]> = [
  [/\brm\s+(-[a-zA-Z]*r[a-zA-Z]*f|-[a-zA-Z]*f[a-zA-Z]*r)\b/, 'rm -rf deletes recursively with no confirmation'],
  [/\brm\s+(-\w+\s+)*(-r|-R|--recursive)\b.*\s(-f|--force)\b/, 'rm -r -f deletes recursively with no confirmation'],
  [/\brm\s+(-\w+\s+)*(-f|--force)\b.*\s(-r|-R|--recursive)\b/, 'rm -f -r deletes recursively with no confirmation'],
  [/\bgit\s+reset\s+--hard\b/, 'git reset --hard throws away uncommitted work'],
  [/\bgit\s+clean\s+-\w*f/, 'git clean -f deletes untracked files'],
  [/\bgit\s+push\b.*(\s-f\b|--force\b)/, 'force push rewrites remote history'],
  [/\bgit\s+checkout\s+(--\s+)?\.(\s|$)/, 'git checkout . discards every local change'],
  [/\bfind\b.*\s-delete\b/, 'find -delete removes every match'],
  [/\bdd\b.*\bof=/, 'dd of= overwrites a file or disk'],
  [/\bmkfs(\.\w+)?\b/, 'mkfs formats a filesystem'],
  [/>\s*\/dev\/(sd|disk|nvme)/, 'writing straight to a disk device'],
  [/\bchmod\s+-R\s+777\b/, 'chmod -R 777 opens every file to everyone'],
  [/:\(\)\s*\{\s*:\|:&\s*\};:/, 'fork bomb'],
]

// Folders a build or install recreates, so rm -rf on them loses nothing.
const REBUILDABLE = new Set([
  'node_modules', 'dist', 'build', 'out', '.next', '.nuxt', '.turbo',
  '.cache', '.parcel-cache', 'coverage', '.vite', '.svelte-kit',
])

const RM = /^\s*rm\s/

// True when a lone rm names only rebuildable folders: plain relative or
// absolute paths, no globs, variables, subshells, quotes, ~ or `..`.
function onlyRebuildable(segment: string): boolean {
  const words = segment.trim().split(/\s+/).slice(1)
  const paths = words.filter(w => !w.startsWith('-'))
  if (paths.length === 0) return false
  return paths.every(p => {
    if (/[*?[\]{}$`~'"\\]/.test(p)) return false
    const parts = p.replace(/\/+$/, '').split('/').filter(s => s !== '' && s !== '.')
    if (parts.includes('..') || parts.length === 0) return false
    return REBUILDABLE.has(parts[parts.length - 1]!)
  })
}

export function destructive(command: string): string | undefined {
  // Judge each command of a chain on its own, so `rm -rf dist && rm -rf src` still blocks.
  for (const segment of command.split(/&&|\|\||[;|\n&]/)) {
    for (const [re, why] of DESTRUCTIVE) {
      if (!re.test(segment)) continue
      if (RM.test(segment) && onlyRebuildable(segment)) continue
      return why
    }
  }
  return undefined
}

// What the call reaches, as text, per tool; undefined for tools that touch no files.
export function targets(tool: string, input: Record<string, unknown>): string[] {
  const keys: Record<string, string[]> = {
    Bash: ['command'],
    Read: ['file_path'],
    Write: ['file_path'],
    Edit: ['file_path'],
    MultiEdit: ['file_path'],
    NotebookEdit: ['notebook_path'],
    Grep: ['path', 'glob'],
    Glob: ['pattern', 'path'],
  }
  return (keys[tool] ?? []).map(k => input[k]).filter((v): v is string => typeof v === 'string')
}

export function verdict(tool: string, input: Record<string, unknown>): string | undefined {
  for (const t of targets(tool, input)) {
    const env = touchesEnv(t)
    if (env) return `${tool} touches ${env}, which holds secrets`
  }
  if (tool === 'Bash' && typeof input.command === 'string') {
    const why = destructive(input.command)
    if (why) return `${why}: ${input.command.slice(0, 80)}`
  }
  return undefined
}

